import * as React from "react";
import Layout from "../components/layout";
import { graphql, HeadFC, PageProps } from "gatsby";
import { Link } from "gatsby";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Palette from "../components/palette";
import EmailForm from "../components/emailForm";
import SEO from "../components/seo";
import images, { mosaicImages } from "../images";
import BlackFridayPopup from "../components/blackFridayPopup";
import ContactBar from "../components/Contact_bar";

const userData = data;

const companyData: Company = {
  whatsapp: "",
  companyName: data.name,
  address: data.address,
  city: data.city,
  province: data.province,
  country: "Canada",
  phone: data.phone,
  email: data.email,
  instagram: data.instagram,
  facebook: data.facebook,
  menu: data.menu,
  linkedin: "",
  postalCode: data.postalCode,
  url: data.url,
};

const homeDescription = [data.address, data.city, data.province]
  .filter(Boolean)
  .join(", ");

const mosaicImageById = Object.fromEntries(
  mosaicImages.map((image) => [image.id, image]),
);

const mosaicColumns = [
  ["mexico", "italy", "colombia"],
  ["canada", "greece"],
  ["portugal", "spain", "france"],
  ["united-kingdom", "united-states"],
] as const;

const featuredExperiences = [
  { id: "adventure", image: images.adventure },
  { id: "wellness", image: images.wellness },
  { id: "gastronomy", image: images.gastronomy },
  { id: "culture", image: images.culture },
] as const;



const IndexPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout data={userData}>
      <BlackFridayPopup />
      {/* <Palette /> */}
      <section className={styles.container}>

        <article className="hero p-4">
          <img className="shadow-2xl" src={images.venice.src } alt={images.venice.alt} />
        </article>

        <article className="p-4">
          <h2 className={styles.title}>{t("home.tailorMadeTours")}</h2>
          <p className={styles.slogan}>{t("home.slogan")}</p>
        </article>

        <article className="inline-flex p-4 gap-4 flex-row items-center justify-center">
          <Link to="/vacations" className={styles.sectorLink}>
            <figure className={styles.sector_image_wrapper}>
              <img className={styles.sector_image} src={images.cabos.src} alt={images.cabos.alt} />
              <span className={styles.slogan}>{t("home.vacations")}</span>
            </figure>
          </Link>
          <Link to="/tours" className={styles.sectorLink}>
            <figure className={styles.sector_image_wrapper}>
              <img className={styles.sector_image} src={images.tours.src} alt={images.tours.alt} />
              <span className={styles.slogan}>{t("home.tours")}</span>
            </figure>
          </Link>
          <Link to="/cruises" className={styles.sectorLink}>
            <figure className={styles.sector_image_wrapper}>
              <img className={styles.sector_image} src={images.cruisers.src} alt={images.cruisers.alt} />
              <span className={styles.slogan}>{t("home.Cruises")}</span>
            </figure>
          </Link>
        </article>


        <ContactBar
          title={t("contactBar.title")}
          ctaLabel={t("contactBar.ctaLabel")}
          ctaHref="/contact"
          certifications={[
            { label: "ACTA", href: "https://..." },
            { label: "TICO", href: "https://..." },
          ]}
        />


        <article className={styles.mosaicSection}>
          <div className={styles.mosaicShell}>
            <h2 className={styles.mosaicHeading}>{t("home.mosaicHeading")}</h2>
            <p className={styles.mosaicSubheading}>
              {t("home.mosaicSubheading")}
            </p>

            <div className={styles.mosaicGrid}>
              {mosaicColumns.map((column, columnIndex) => (
                <div key={`column-${columnIndex}`} className={styles.mosaicColumn}>
                  {column.map((imageId) => {
                    const image = mosaicImageById[imageId];
                    if (!image) {
                      return null;
                    }

                    return (
                      <figure key={image.id} className={styles.mosaicCard}>
                        <img className={styles.mosaicImage} src={image.src} alt={image.alt} />
                        <figcaption className={styles.mosaicTitle}>{image.title}</figcaption>
                      </figure>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>
        </article>


        <article className={styles.experienceSection}>
          <div className={styles.experienceShell}>
            <h2 className={styles.experienceHeading}>{t("home.experienceHeading")}</h2>
            <p className={styles.experienceSubheading}>{t("home.experienceSubheading")}</p>

            <div className={styles.experienceGrid}>
              {featuredExperiences.map(({ id, image }) => (
                <figure key={id} className={styles.experienceCard}>
                  <img className={styles.experienceImage} src={image.src} alt={image.alt || id} />
                  <figcaption className={styles.experienceCaption}>
                    {id.toUpperCase()}
                  </figcaption>
                </figure>
              ))}
            </div>
          </div>
        </article>

      </section>
    </Layout>
  )
}

export default IndexPage

export const Head: HeadFC = ({ pageContext }) => {
  const i18n = (pageContext as
    | {
        i18n?: {
          language?: string;
          languages?: string[];
          defaultLanguage?: string;
          originalPath?: string;
        };
      }
    | undefined)?.i18n;

  return (
    <SEO
      data={companyData}
      title={userData.name}
      description={homeDescription || userData.name}
      schemaName={userData.name}
      pathname="/"
      language={i18n?.language}
      languages={i18n?.languages}
      defaultLanguage={i18n?.defaultLanguage}
      originalPath={i18n?.originalPath}
    />
  );
};


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

