import React from "react";
import data from "../data/data.json";
import images from "../images";
import { IoLogoWhatsapp } from "react-icons/io";
import { useTranslation } from "gatsby-plugin-react-i18next";

export type ContactBarCertification = {
  label: string;
  href: string;
};

export interface ContactBarProps {
  title: string;
  imageSrc?: string;
  imageAlt?: string;
  ctaLabel: string;
  ctaHref: string;
  certifications?: ContactBarCertification[];
  certificationsTitle?: string;
  phone?: string;
  whatsApp?: string;
  className?: string;
}

const defaultData = data as {
  phone?: string;
  whatsApp?: string;
};

function formatPhone(phone?: string): string {
  if (!phone) {
    return "";
  }
  const cleaned = phone.replace(/\D+/g, "");
  if (cleaned.length === 11 && cleaned.startsWith("1")) {
    return `+1 ${cleaned.slice(1, 4)} ${cleaned.slice(4, 7)} ${cleaned.slice(7)}`;
  }
  return phone;
}

const ContactBar: React.FC<ContactBarProps> = ({
  title,
  imageSrc = images.logo.src,
  imageAlt = "Contact",
  ctaLabel,
  ctaHref,
  certifications = [],
  certificationsTitle = "Certifications:",
  phone = defaultData.phone,
  whatsApp = defaultData.whatsApp,
  className = "",
}) => {
  const { t } = useTranslation();

  return (
    <section className={`${styles.section} ${className}`}>
      <div className={styles.inner}>
        <div className={styles.imageWrap} aria-hidden="true">
          <img src={imageSrc} alt={imageAlt} className={styles.image} />
        </div>

        <div className={styles.columns}>
          <div className={styles.content}>
            <figure className={styles.jennyWrap}>
              <img className={styles.jennyImage} src={images.jenny.src} alt={images.jenny.alt} />
            </figure>

            <div className={styles.copy}>
              <h3 className={styles.title}>{title}</h3>
              <p className={styles.description}>
                {t("contactBar.description")}
              </p>
            </div>
          </div>

          <div className={styles.contactLinks}>
            {phone ? (
              <div className={styles.contactItem}>
                <span className={styles.contactLabel}>{t("contactBar.phone")}</span>
                <a href={`tel:${phone}`} className={styles.link}>
                  {formatPhone(phone)}
                </a>
              </div>
            ) : null}
            {whatsApp ? (
              <div className={styles.contactItem}>
                <span className={styles.contactLabel}>{t("contactBar.whatsApp")}</span>
                <a href={whatsApp} className={styles.whatsAppLink}>
                  <IoLogoWhatsapp className="text-[#25D366] text-3xl" />
                  <span>Chat</span>
                </a>
              </div>
            ) : null}
          </div>

          <a href={ctaHref} className={styles.cta}>
            {ctaLabel}
          </a>
        </div>
      </div>

      {certifications.length > 0 ? (
        <div className={styles.certifications}>
          <span className={styles.certificationsTitle}>{certificationsTitle}</span>
          <div className={styles.certificationsLinks}>
            {certifications.map((certification) => (
              <a
                key={`${certification.label}-${certification.href}`}
                href={certification.href}
                target="_blank"
                rel="noreferrer"
                className={styles.certificationLink}
              >
                {certification.label}
              </a>
            ))}
          </div>
        </div>
      ) : null}
    </section>
  );
};

export default ContactBar;

const styles = {
  section: "w-full overflow-hidden bg-secondary text-contrast shadow-xl",
  inner:
    "relative isolate mx-auto w-full max-w-[1400px] pb-0 px-4 py-6 sm:px-8 sm:pt-8",
  imageWrap:
    "pointer-events-none absolute left-1/2 top-1/2 z-0 flex -translate-x-1/2 -translate-y-1/2 justify-center opacity-10 lg:left-auto lg:right-0 lg:translate-x-1/4",
  image: "h-[20rem] w-[20rem] object-contain sm:h-[28rem] sm:w-[28rem] lg:h-[36rem] lg:w-[36rem]",
  columns:
    "relative z-10 grid w-full gap-8 lg:grid-cols-[minmax(0,1.6fr)_minmax(12rem,0.8fr)_auto] lg:items-center",
  content:
    "flex flex-col items-center gap-4 text-center sm:flex-row sm:text-left",
  jennyWrap: "shrink-0",
  jennyImage: "h-32 w-32 rounded-full object-cover border-2 border-contrast/40 sm:h-36 sm:w-36",
  copy: "flex max-w-xl flex-col gap-2",
  title: "h1_desk text-contrast",
  description: "body_desk text-contrast/90",
  contactLinks: "flex flex-col gap-4 text-center sm:text-left lg:justify-self-center",
  contactItem: "flex flex-col gap-1",
  contactLabel: "subtext_desk uppercase tracking-wide text-contrast/80",
  link: "suptext_desk text-contrast transition-colors duration-200 hover:text-main",
  whatsAppLink:
    "suptext_desk inline-flex items-center justify-center gap-2 rounded-full bg-contrast px-4 py-2 text-secondary transition-colors duration-200 hover:bg-main sm:justify-start",
  certifications:
    "mx-auto flex w-full max-w-[1400px] flex-col items-center gap-3 border-t border-contrast/15 px-4 py-2 text-center sm:px-8 lg:flex-row lg:justify-center lg:text-left",
  certificationsTitle: "subtext_desk shrink-0 text-contrast/90 uppercase tracking-wide",
  certificationsLinks: "flex flex-wrap items-center justify-center gap-2",
  certificationLink:
    "subtext_desk text-contrast border border-contrast/40 px-2 py-1 hover:bg-contrast/10 transition-colors duration-200",
  cta:
    "menu_desk inline-flex min-h-[52px] items-center justify-center rounded-full bg-terciary px-6 py-3 font-semibold whitespace-nowrap text-contrast transition-colors duration-200 hover:bg-contrast hover:text-secondary lg:justify-self-end"
};
